import{_ as s,o as t,c as a,ag as n}from"./chunks/framework.DMVuHR7L.js";const u=JSON.parse('{"title":"Docs conventions","description":"","frontmatter":{},"headers":[],"relativePath":"devs/docs-conventions.md","filePath":"devs/docs-conventions.md","lastUpdated":1778778099000}'),i={name:"devs/docs-conventions.md"};function o(l,e,d,c,r,p){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="docs-conventions" tabindex="-1">Docs conventions <a class="header-anchor" href="#docs-conventions" aria-label="Permalink to &quot;Docs conventions&quot;">​</a></h1><p>The documentation site lives under <code>docs/</code>. It&#39;s published as a separate VitePress app at <code>&lt;app&gt;/docs/</code> (production: <code>https://gabrielhuff.github.io/web-logcat/docs/</code>).</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/</span></span>
<span class="line"><span>├── .vitepress/config.ts          # navigation, sidebar, base path, theme</span></span>
<span class="line"><span>├── public/                       # static assets (favicon, hero PNG)</span></span>
<span class="line"><span>├── index.md                      # landing page</span></span>
<span class="line"><span>├── features/                     # user-facing product docs</span></span>
<span class="line"><span>│   ├── index.md</span></span>
<span class="line"><span>│   ├── img/                      # screenshots referenced from features/*.md</span></span>
<span class="line"><span>│   └── &lt;feature&gt;.md</span></span>
<span class="line"><span>├── devs/                         # contributor / human reference (this section)</span></span>
<span class="line"><span>│   ├── index.md</span></span>
<span class="line"><span>│   └── &lt;topic&gt;.md</span></span>
<span class="line"><span>└── bots/                         # agent-only contracts (intentionally terse)</span></span>
<span class="line"><span>    ├── index.md</span></span>
<span class="line"><span>    └── &lt;topic&gt;.md</span></span></code></pre></div><p>The three top-level sections have different audiences and different expectations of polish:</p><table tabindex="0"><thead><tr><th>Section</th><th>Audience</th><th>Tone</th></tr></thead><tbody><tr><td><code>features/</code></td><td>End users (developers using WebLogcat against their own devices)</td><td>Polished, illustrated, focused on usage and behaviour. No design / internals.</td></tr><tr><td><code>devs/</code></td><td>Contributors — humans + bots that benefit from prose</td><td>Reference, lightly polished. Architecture, deploy, release procedure.</td></tr><tr><td><code>bots/</code></td><td>AI agents working in the repo</td><td>Terse contracts. No screenshots, no fluff — the goal is <em>agent succeeds at the task</em>, not <em>human enjoys the read</em>.</td></tr></tbody></table><h2 id="writing-style" tabindex="-1">Writing style <a class="header-anchor" href="#writing-style" aria-label="Permalink to &quot;Writing style&quot;">​</a></h2><ul><li>Sentences over checklists where the prose is short. Tables and bullet lists when the structure earns its keep.</li><li>Code blocks use the language tag (<code>\`\`\`ts</code>, <code>\`\`\`bash</code>) so VitePress syntax highlighting kicks in.</li><li>Internal links use the relative path <em>without</em> the <code>.md</code> suffix (<code>./logcat</code>, <code>../bots/widgets-contract</code>) — VitePress&#39;s <code>cleanUrls</code> is on.</li><li>The &quot;Open WebLogcat&quot; link in the navbar is automatic — don&#39;t sprinkle absolute production URLs through the prose. If you must, point at the staging URL so writing on <code>main</code> doesn&#39;t ship a link the reader can&#39;t yet hit.</li></ul><h2 id="screenshots" tabindex="-1">Screenshots <a class="header-anchor" href="#screenshots" aria-label="Permalink to &quot;Screenshots&quot;">​</a></h2><p>Feature pages live or die on screenshots. The convention:</p><ul><li>Feature shots live under <code>docs/features/img/&lt;slug&gt;.png</code>. Reference them with relative paths: <code>![alt](./img/&lt;slug&gt;.png)</code>.</li><li>One canonical hero shot per feature, plus task-specific shots if a flow is non-obvious. Keep PNGs under ~250 KB; prefer 2× device-pixel resolution for crispness.</li><li>Most shots come out of <code>scripts/capture-feature-screenshots.ts</code> — a Playwright script that drives the <a href="./../features/simulator">simulator</a> and snapshots each widget. Run <code>npm run docs:screenshots</code> after a UI change that affects how the rendered shot looks; review the diff in the PR.</li><li>Real-device-only flows (Mirror&#39;s live frame, Files transfers, the WebUSB pairing dialog) cannot be captured by the script. Use a real device and commit the static PNG; flag the source in the alt-text.</li><li>Avoid embedding live device serials, IPs, or other personally identifying information. The simulator&#39;s defaults are safe; if you capture against a real device, redact the serial in the device pill.</li></ul><h2 id="keeping-docs-in-sync-with-the-app" tabindex="-1">Keeping docs in sync with the app <a class="header-anchor" href="#keeping-docs-in-sync-with-the-app" aria-label="Permalink to &quot;Keeping docs in sync with the app&quot;">​</a></h2><blockquote><p><strong>Contract.</strong> Every PR that changes user-facing behaviour updates the matching feature page in the same PR. Reviewers will block merges that drift.</p></blockquote><p>Concretely:</p><ul><li>Adding a widget kind → new <code>docs/features/&lt;kind&gt;.md</code>, plus a row in <code>docs/features/index.md</code> and a sidebar entry in <code>.vitepress/config.ts</code>.</li><li>Renaming a UI control / shortcut → grep <code>docs/features/</code> for the old name and update.</li><li>Removing a feature → delete the page, drop its sidebar entry, sweep inbound links.</li><li>Changing the appearance / layout of a tile → re-run <code>npm run docs:screenshots</code> and review the captured PNG before committing.</li></ul><p>The agent-facing version of this contract lives at <a href="./../bots/doc-sync">bots/doc-sync</a> — it&#39;s the one a bot will read first.</p><div class="tip custom-block"><p class="custom-block-title">Editing the agent contracts themselves</p><p>The <code>bots/</code> directory is meant to grow with the codebase as agents fold their learnings in. The rules for doing that safely (what to update, what&#39;s load-bearing, the size budget) live in <a href="./../bots/maintaining">bots/maintaining</a>. Read it before pushing changes under <code>bots/</code>.</p></div><h2 id="building-locally" tabindex="-1">Building locally <a class="header-anchor" href="#building-locally" aria-label="Permalink to &quot;Building locally&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # dev server on http://localhost:5174</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # build into dist/docs/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:preview</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # preview the built output</span></span></code></pre></div><p>The production build is part of the <code>deploy</code> workflow&#39;s <code>build:all</code> step — see <a href="./deployment">deployment</a>.</p>`,20)])])}const g=s(i,[["render",o]]);export{u as __pageData,g as default};
